// "Ask a local" chat: POST /api/ask streams a short answer written by Claude from the site's own facts
// (src/knowledge.js, generated by build.py). GET /api/ask says whether the chat is switched on.
// Needs the Worker secret ANTHROPIC_API_KEY; without it the chat stays hidden on the site.
import Anthropic from '@anthropic-ai/sdk';
import KNOWLEDGE from './knowledge.js';

const MODEL = 'claude-opus-5-5';
const MAX_TURNS = 10;          // messages kept from the conversation (user + assistant)
const MAX_QUESTION = 600;      // characters per visitor message
const MAX_ANSWER_ECHO = 3000;  // characters per earlier answer sent back as history

const INSTRUCTIONS = `You are "Ask a local", the chat assistant on HCMC Insider (hcmcinsider.com), an independent English guide to Ho Chi Minh City (Saigon) written by locals. Visitors ask you about food, sights, getting around and planning a trip.

How to answer:
- Base specific facts (places, addresses, opening hours, prices, routes, dates) only on the site knowledge below. If the site does not cover something, say so plainly; you may add widely known general advice, but never invent a place, price, opening hour or date. For anything the site cannot answer, visitors can email hello@hcmcinsider.com.
- Recommend places from the site and link their pages as markdown links, e.g. [Phat Ky](https://hcmcinsider.com/places/phat-ky/). Only use hcmcinsider.com links that appear in the knowledge. Give the Vietnamese name next to the English one, since visitors show it to drivers and sellers.
- Hours and prices change; when the answer depends on them, say to check before going, and mention the "Last checked" date if it is old.
- Be brief and warm, like a local friend: usually 2–6 sentences or a short list. Plain text with markdown links, **bold** and "- " lists only. Answer in the visitor's language.
- Stay on travel in Ho Chi Minh City and Vietnam. Politely decline unrelated tasks.
- Do not give medical, legal or visa advice beyond pointing to official sources.

SITE KNOWLEDGE
`;

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });

function cleanMessages(input) {
  if (!Array.isArray(input) || !input.length) return null;
  const msgs = input.slice(-MAX_TURNS).map((m) => ({
    role: m && m.role === 'assistant' ? 'assistant' : 'user',
    content: String((m && m.content) || '').trim(),
  })).filter((m) => m.content);
  while (msgs.length && msgs[0].role !== 'user') msgs.shift();
  if (!msgs.length || msgs[msgs.length - 1].role !== 'user') return null;
  for (const m of msgs) {
    if (m.role === 'user' && m.content.length > MAX_QUESTION) return null;
    if (m.role === 'assistant') m.content = m.content.slice(0, MAX_ANSWER_ECHO);
  }
  return msgs;
}

function saigonToday() {
  return new Date(Date.now() + 7 * 3600e3).toISOString().slice(0, 10) +
    ' (' + ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][new Date(Date.now() + 7 * 3600e3).getUTCDay()] + ')';
}

export async function handleAsk(request, env, ctx) {
  if (request.method === 'GET') return json({ ready: Boolean(env.ANTHROPIC_API_KEY) });
  if (request.method !== 'POST') return json({ error: 'method' }, 405);
  if (!env.ANTHROPIC_API_KEY) return json({ error: 'The chat is not switched on yet.' }, 503);

  // Only our own pages may call the chat (browsers always send Origin on a POST from a page).
  if (request.headers.get('Origin') !== new URL(request.url).origin) return json({ error: 'forbidden' }, 403);

  if (env.ASK_LIMITER) {
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const { success } = await env.ASK_LIMITER.limit({ key: ip });
    if (!success) return json({ error: 'Too many questions in a short time. Please wait a minute and try again.' }, 429);
  }

  let body;
  try { body = await request.json(); } catch { return json({ error: 'Bad request.' }, 400); }
  const messages = cleanMessages(body && body.messages);
  if (!messages) return json({ error: `Please keep your question under ${MAX_QUESTION} characters.` }, 400);

  // ANTHROPIC_BASE_URL is only for local testing against a mock server; leave it unset in production.
  const client = new Anthropic({ apiKey: env.ANTHROPIC_API_KEY, baseURL: env.ANTHROPIC_BASE_URL || undefined, maxRetries: 1 });
  const { readable, writable } = new TransformStream();
  const writer = writable.getWriter();
  const enc = new TextEncoder();

  const run = async () => {
    let wrote = false;
    try {
      const stream = client.beta.messages.stream({
        model: MODEL,
        max_tokens: 8000,
        betas: ['server-side-fallback-2026-07-01'],
        fallbacks: 'default',
        output_config: { effort: 'low' },
        system: [
          // The big, stable block is cached; the date comes after it so the cache survives day changes.
          { type: 'text', text: INSTRUCTIONS + KNOWLEDGE, cache_control: { type: 'ephemeral', ttl: '1h' } },
          { type: 'text', text: 'Today in Saigon: ' + saigonToday() + '.' },
        ],
        messages,
      });
      for await (const event of stream) {
        if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
          wrote = true;
          await writer.write(enc.encode(event.delta.text));
        }
      }
      const final = await stream.finalMessage();
      if (final.stop_reason === 'refusal' && !wrote) {
        await writer.write(enc.encode("Sorry, I can't help with that one. For questions about the site, email hello@hcmcinsider.com."));
      } else if (final.stop_reason === 'max_tokens') {
        await writer.write(enc.encode('…'));
      }
    } catch (err) {
      const msg = err instanceof Anthropic.RateLimitError
        ? 'The chat is busy right now. Please try again in a minute.'
        : 'Sorry, something went wrong. Please try again.';
      console.error('ask failed', err && err.status, err && err.message);
      await writer.write(enc.encode((wrote ? '\n\n' : '') + msg));
    } finally {
      await writer.close();
    }
  };
  ctx.waitUntil(run());
  return new Response(readable, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' },
  });
}
